CustomField.formula:
AND(
    /* Not Cancelled */
    NOT(ISPICKVAL(Order_Header__r.Status__c, "Cancelled")),
    /* Region 29/0029 OR Item Class in list OR Item Class Family + Vendor */
    OR(
        CONTAINS(
            ";29;0029;",
            ";" & Order_Header__r.Region__c & ";"
        ),
        CONTAINS(
            ";AP;AP01J;AP01P;AP02X;AP03X;AP05J;AP06P;AP07J;AP07P;AP08J;AP08P;CD;CD07D;CD09P;CD10D;CD10P;CD12D;CD12P;CD13D;CD14P;CD15P;CO01C;CP01;CP03P;CP09P;CR06C;CSFO;CU01P;DB;ECPE;FO02C;FO03C;FO03F;FO03G;FO03U;FO03X;FO03Y;FO03Z;FO51P;FOOUT;FP01C;FP02C;FP02J;FP02P;FP03C;FP03F;FP03P;FP04P;FP05;FP06P;FP07C;FP08C;FP09P;PB;PB01P;PB05D;TT01P;TT02F;TT02I;TT03I;TT03P;TT04I;UG;UG01P;UG05Y;UGH01;UGY01;UGY02;",
            ";" & Item_Class__c & ";"
        ),
        AND(
            CONTAINS(
                ";AP;BE;CS;CD;CN;CP;CU;EX;DB;FO;FT;FP;PB;UG;NS;TT;",
                ";" & Item_Class__c & ";"
            ),
            CONTAINS(
                ";31489;31671;33634;33687;33797;33808;33811;33837;33840;33893;34097;34125;34153;50148;50149;60230;",
                ";" & Vendor_Number__c & ";"
            )
        )
    )
)
